from typing import AnyStr, Tuple, Union

class SQLParams:
    in_style: str

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    formatted_sql = sql
    converted_params = params

    # Check if the in_style is named or ordinal
    if isinstance(self.SQLParams.in_style, str):
        # Convert named parameters to out-style parameters
        converted_params = {**params}
    else:
        # Convert ordinal parameters to out-style parameters
        converted_params = params[:]

    return formatted_sql, converted_params

