def size_to_bytes(size: str) -> int:
    # Define conversion factors
    size_factors = {
        'K': 1024,
        'M': 1024**2,
        'G': 1024**3,
        'T': 1024**4,
    }

    # Strip the trailing unit if present
    size = size.rstrip('KMGTP')

    # Convert the size to bytes
    try:
        return int(size) * size_factors[size[-1]]
    except KeyError:
        raise ValueError("Invalid file size unit")

